class CoastalMountainTest{public static void main(String[]args){var g=new TerrainGraph();var base=g.add(TerrainGraph.Type.CONSTANT,0,0);base.values.put("height",110.0);var island=g.add(TerrainGraph.Type.ISLAND,0,0);island.input[0]=base.id;island.values.put("radius",1.1);island.values.put("depth",160.0);var m=g.add(TerrainGraph.Type.MOUNTAIN,0,0);m.input[0]=island.id;m.values.put("x",50.0);m.values.put("z",50.0);m.values.put("radius",35.0);int n=128;var land=g.evaluate(n,4096,62,2024,island.id,()->false).output();var old=g.evaluate(n,4096,62,2024,m.id,()->false).output();m.values.put("coastalReach",1024.0);var gentle=g.evaluate(n,4096,62,2024,m.id,()->false).output();var distance=EnvironmentNodes.distanceToSea(land,n,62,()->false);int softened=0;for(int i=0;i<land.length;i++){if(land[i]<=62&&gentle[i]!=land[i])throw new AssertionError("Ocean changed");if(distance[i]*32<512&&old[i]>land[i]+5&&gentle[i]<old[i]-2)softened++;}if(softened<50||gentle[64*n+64]<old[64*n+64]-.01)throw new AssertionError("Coastal taper or interior peak lost: "+softened);System.out.println("PASS: coastal slopes taper gently, ocean unchanged, inland summit preserved");}}
